<script setup>
import { onMounted, reactive, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import { useRiderStore } from '../../stores/rider';
import RiderDetailDrawer from '../../components/fleet/RiderDetailDrawer.vue';
import AssignOrdersModal from '../../components/fleet/AssignOrdersModal.vue';
import { axios } from '../../lib/echo';

const store = useRiderStore(); const route = useRoute();
const filters = reactive({ search: '', archipelago_id: '', hub_id: '', status: '', vehicle_type: '', page: 1, per_page: 10 });
const archipelagos = ref([]); const hubs = ref([]); const detailRider = ref(null); const assignmentRider = ref(null); const pending = ref(new Set()); let timer;
const statusClass = { available: 'bg-emerald-100 text-emerald-800', on_delivery: 'bg-blue-100 text-blue-800', off_duty: 'bg-slate-100 text-slate-700', suspended: 'bg-red-100 text-red-800' };
const label = (value) => value?.replaceAll('_', ' ');
const load = () => store.fetchRiders({ ...filters, archipelago_id: filters.archipelago_id || undefined, hub_id: filters.hub_id || undefined, status: filters.status || undefined, vehicle_type: filters.vehicle_type || undefined });
const search = () => { clearTimeout(timer); timer = setTimeout(() => { filters.page = 1; load(); }, 300); };
const toggle = async (rider) => { const old = rider.status; const next = old === 'available' ? 'off_duty' : 'available'; rider.status = next; pending.value.add(rider.id); try { await store.updateStatus(rider.id, next); } catch (_) { rider.status = old; } finally { pending.value.delete(rider.id); } };
const reload = () => { detailRider.value = null; assignmentRider.value = null; load(); };
watch(() => [filters.archipelago_id, filters.hub_id, filters.status, filters.vehicle_type], () => { filters.page = 1; load(); });
onMounted(async () => { store.auth(); archipelagos.value = (await axios.get('/archipelagos')).data; hubs.value = (await axios.get('/hubs')).data; await load(); if (route.query.assign) assignmentRider.value = store.riders.data.find((rider) => rider.status === 'available') || null; });
</script>

<template>
  <main class="min-h-screen bg-[#f4f7f6] text-slate-900"><header class="border-b border-slate-200 bg-white"><div class="mx-auto max-w-7xl px-6 py-6"><p class="text-xs font-black uppercase tracking-[0.22em] text-teal-700">Fleet operations</p><div class="mt-1 flex flex-wrap items-center justify-between gap-4"><h1 class="text-3xl font-black">Rider directory</h1><span class="text-sm font-semibold text-slate-500">{{ store.riders.total }} riders</span></div></div></header><div class="mx-auto max-w-7xl px-6 py-8"><section class="border border-slate-200 bg-white shadow-sm"><div class="grid gap-3 border-b border-slate-200 p-5 md:grid-cols-2 lg:grid-cols-5"><input v-model="filters.search" @input="search" placeholder="Search rider or plate" class="border border-slate-300 px-3 py-2 text-sm outline-none focus:border-teal-500" /><select v-model="filters.archipelago_id" class="border border-slate-300 px-3 py-2 text-sm"><option value="">All archipelagos</option><option v-for="item in archipelagos" :key="item.id" :value="item.id">{{ item.name }}</option></select><select v-model="filters.hub_id" class="border border-slate-300 px-3 py-2 text-sm"><option value="">All hubs</option><option v-for="hub in hubs" :key="hub.id" :value="hub.id">{{ hub.name }}</option></select><select v-model="filters.status" class="border border-slate-300 px-3 py-2 text-sm"><option value="">All duty status</option><option v-for="status in ['available','on_delivery','off_duty','suspended']" :key="status" :value="status">{{ label(status) }}</option></select><select v-model="filters.vehicle_type" class="border border-slate-300 px-3 py-2 text-sm"><option value="">All vehicles</option><option v-for="type in ['motorcycle','tricycle','van','truck']" :key="type">{{ type }}</option></select></div><div v-if="store.error" class="m-5 bg-red-50 px-4 py-3 text-sm text-red-700">{{ store.error }}</div><div class="overflow-x-auto"><table class="w-full min-w-[900px] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wider text-slate-500"><tr><th class="px-5 py-3">Rider</th><th class="px-5 py-3">Hub</th><th class="px-5 py-3">Vehicle</th><th class="px-5 py-3">Duty status</th><th class="px-5 py-3">Performance</th><th class="px-5 py-3 text-right">Actions</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-if="store.loading"><td colspan="6" class="p-10 text-center text-slate-400">Loading rider directory...</td></tr><tr v-for="rider in store.riders.data" v-else :key="rider.id" class="hover:bg-teal-50/30"><td class="px-5 py-4"><div class="font-bold">{{ rider.user?.name }}</div><div class="text-slate-500">{{ rider.phone_number || rider.user?.email }}</div></td><td class="px-5 py-4 text-slate-600">{{ rider.hub?.name }}</td><td class="px-5 py-4 capitalize"><div>{{ rider.vehicle_type }}</div><div class="font-mono text-xs text-slate-500">{{ rider.plate_number || 'No plate' }}</div></td><td class="px-5 py-4"><button class="inline-flex items-center gap-2 px-2.5 py-1 text-xs font-bold capitalize disabled:opacity-50" :class="statusClass[rider.status]" :disabled="pending.has(rider.id) || rider.status === 'suspended'" @click="toggle(rider)"><span class="h-2 w-2 rounded-full bg-current" />{{ label(rider.status) }}</button></td><td class="px-5 py-4"><strong>{{ Number(rider.performance?.on_time_rate || 0).toFixed(1) }}%</strong><span class="ml-2 text-slate-400">{{ rider.performance?.total_completed || 0 }} completed</span></td><td class="space-x-3 px-5 py-4 text-right"><button class="font-semibold text-teal-700" @click="detailRider = rider">Details</button><button v-if="rider.status === 'available'" class="font-semibold text-slate-700" @click="assignmentRider = rider">Assign</button></td></tr><tr v-if="!store.loading && !store.riders.data.length"><td colspan="6" class="p-10 text-center text-slate-400">No riders match these filters.</td></tr></tbody></table></div><footer class="flex justify-between border-t border-slate-200 px-5 py-4 text-sm"><span class="text-slate-500">Page {{ store.riders.current_page }} of {{ store.riders.last_page }}</span><div class="flex gap-2"><button :disabled="store.riders.current_page <= 1" class="border px-3 py-1.5 disabled:opacity-40" @click="filters.page--; load()">Previous</button><button :disabled="store.riders.current_page >= store.riders.last_page" class="border px-3 py-1.5 disabled:opacity-40" @click="filters.page++; load()">Next</button></div></footer></section></div><div v-if="detailRider" class="fixed inset-0 z-20 bg-slate-950/30" @click.self="detailRider = null"><RiderDetailDrawer :rider="detailRider" @close="detailRider = null" /></div><AssignOrdersModal v-if="assignmentRider" :rider="assignmentRider" @close="assignmentRider = null" @assigned="reload" /></main>
</template>